"""
views/vm_template_dialog.py

"New from Template" — lets the user pick a BulwarkOS predefined AppVM template,
optionally adjust resources, then provision it.

Flow:
  1. Template picker — grid of cards (Personal, Work, Banking, etc.)
  2. Clicking a card either goes straight to Create (with defaults) or
     expands an "Advanced" section for resource adjustment.
  3. Clicking Create shows VMCreationOverlay — a centred progress sheet.
"""

import gi
gi.require_version("Gtk", "4.0")
gi.require_version("Adw", "1")

import subprocess, os
from pathlib import Path
from typing import Callable

from gi.repository import Gtk, Adw, Gdk, GLib
from .svg_assets import make_shield_image, make_template_icon_image

from ..backend.libvirt_manager import LibvirtManager

# ---------------------------------------------------------------------------
# CSS — card lift animation and selection treatment
# ---------------------------------------------------------------------------

_CARD_CSS = (
    b"flowbox > flowboxchild:selected,"
    b"flowbox > flowboxchild:selected:focus {"
    b"  background: transparent; outline: none; box-shadow: none; }"
    b" .tmpl-card {"
    b"  border-radius: 12px;"
    b"  transition: transform 120ms ease, box-shadow 120ms ease;"
    b"  transform: translateY(0px); }"
    b" .tmpl-card.hover {"
    b"  transform: translateY(-4px);"
    b"  box-shadow: 0 6px 18px rgba(0,0,0,0.35); }"
    b" .tmpl-card.pressed {"
    b"  transform: translateY(-2px);"
    b"  box-shadow: 0 3px 8px rgba(0,0,0,0.25); }"
    b" .tmpl-card.selected {"
    b"  border: 2px solid @accent_color;"
    b"  transform: translateY(-4px);"
    b"  box-shadow: 0 6px 18px rgba(0,0,0,0.35); }"
)

_css_loaded = False

def _ensure_card_css():
    global _css_loaded
    if _css_loaded:
        return
    provider = Gtk.CssProvider()
    provider.load_from_data(_CARD_CSS)
    Gtk.StyleContext.add_provider_for_display(
        Gdk.Display.get_default(),
        provider,
        Gtk.STYLE_PROVIDER_PRIORITY_APPLICATION,
    )
    _css_loaded = True


