def _build_domain_xml(name: str, tmpl: dict, vcpus: int, memory_mb: int) -> str:
    """Generate libvirt domain XML from a template definition."""
    disk_path = f"{IMAGE_DIR}/{name}.qcow2"
    return f"""<domain type='kvm'>
  <name>{name}</name>
  <title>BulwarkOS — {tmpl['label']} AppVM</title>
  <memory unit='MiB'>{memory_mb}</memory>
  <currentMemory unit='MiB'>{memory_mb}</currentMemory>
  <vcpu placement='static'>{vcpus}</vcpu>
  <os>
    <type arch='x86_64' machine='q35'>hvm</type>
    <loader readonly='yes' type='pflash'>{OVMF_CODE}</loader>
    <nvram template='{OVMF_VARS}'/>
  </os>
  <features><acpi/><apic/></features>
  <cpu mode='host-passthrough' check='none' migratable='off'/>
  <clock offset='utc'>
    <timer name='rtc' tickpolicy='catchup'/>
    <timer name='pit' tickpolicy='delay'/>
    <timer name='hpet' present='no'/>
  </clock>
  <on_poweroff>destroy</on_poweroff>
  <on_reboot>restart</on_reboot>
  <on_crash>destroy</on_crash>
  <devices>
    <emulator>/usr/bin/qemu-system-x86_64</emulator>
    <controller type='scsi' index='0' model='virtio-scsi'/>
    <disk type='file' device='disk'>
      <driver name='qemu' type='qcow2' discard='unmap'/>
      <source file='{disk_path}'/>
      <target dev='sda' bus='scsi'/>
      <boot order='1'/>
    </disk>
    <interface type='network'>
      <source network='{tmpl["network"]}'/>
      <model type='virtio'/>
    </interface>
    <graphics type='spice' autoport='yes'>
      <listen type='address' address='127.0.0.1'/>
      <image compression='off'/>
    </graphics>
    <video>
      <model type='virtio' heads='1' primary='yes'>
        <acceleration accel3d='no'/>
      </model>
    </video>
    <channel type='spicevmc'>
      <target type='virtio' name='com.redhat.spice.0'/>
    </channel>
    <input type='tablet' bus='usb'/>
    <input type='keyboard' bus='virtio'/>
    <memballoon model='virtio'><stats period='5'/></memballoon>
    <rng model='virtio'><backend model='random'>/dev/urandom</backend></rng>
    <serial type='pty'><target type='isa-serial' port='0'/></serial>
    <console type='pty'><target type='serial' port='0'/></console>
  </devices>
</domain>"""


# ---------------------------------------------------------------------------
# Creation progress overlay
# ---------------------------------------------------------------------------

class VMCreationOverlay(Gtk.Window):
    """
    Centred modal sheet shown while a VM is being provisioned.

    Shows the BulwarkOS shield icon, "Creating <name>…", an animated
    progress bar, and a "Go to VM" button with a checkmark that becomes
    active once creation completes.
    """

    # Shield rendered via svg_assets.make_shield_image()

    def __init__(
        self,
        parent: Gtk.Window,
        vm_name: str,
        on_goto: Callable[[str], None],
    ):
        super().__init__()
        self._vm_name  = vm_name
        self._on_goto  = on_goto
        self._done     = False
        self._start_vm = False

        self.set_transient_for(parent)
        self.set_modal(True)
        self.set_resizable(False)
        self.set_default_size(340, 340)
        self.set_decorated(False)

        # Card container
        card = Gtk.Box(orientation=Gtk.Orientation.VERTICAL, spacing=0)
        card.add_css_class("card")
        card.set_margin_top(0)
        card.set_margin_bottom(0)
        card.set_halign(Gtk.Align.FILL)
        card.set_valign(Gtk.Align.FILL)
        self.set_child(card)

        inner = Gtk.Box(orientation=Gtk.Orientation.VERTICAL, spacing=20)
        inner.set_margin_top(40)
        inner.set_margin_bottom(32)
        inner.set_margin_start(40)
        inner.set_margin_end(40)
        inner.set_valign(Gtk.Align.CENTER)
        inner.set_vexpand(True)
        card.append(inner)

        # BulwarkOS shield — uses the real shield-1.svg path via svg_assets
        shield_img = make_shield_image(color="#546ac1", pixel_size=80)
        shield_img.set_halign(Gtk.Align.CENTER)
        inner.append(shield_img)

        # Status label
        self._status_label = Gtk.Label()
        self._status_label.set_markup(
            f"<span size='large' weight='bold'>Creating…</span>\n"
            f"<span color='gray' size='small'>{vm_name}</span>"
        )
        self._status_label.set_justify(Gtk.Justification.CENTER)
        inner.append(self._status_label)

        # Progress bar
        self._progress = Gtk.ProgressBar()
        self._progress.set_pulse_step(0.06)
        self._progress.set_hexpand(True)
        inner.append(self._progress)

        # Start pulsing
        self._pulse_source = GLib.timeout_add(80, self._pulse)

        # "Start VM on exit" toggle
        self._start_toggle = Gtk.CheckButton(
            label="Start VM when done"
        )
        self._start_toggle.set_active(True)
        self._start_toggle.set_halign(Gtk.Align.CENTER)
        self._start_toggle.set_sensitive(False)
        self._start_toggle.connect("toggled", lambda b: setattr(self, "_start_vm", b.get_active()))
        inner.append(self._start_toggle)

        # "Go to VM" button — insensitive until done
        self._goto_btn = Gtk.Button()
        goto_inner = Gtk.Box(orientation=Gtk.Orientation.HORIZONTAL, spacing=8)
        goto_inner.set_halign(Gtk.Align.CENTER)
        self._goto_checkmark = Gtk.Image.new_from_icon_name("object-select-symbolic")
        self._goto_checkmark.set_pixel_size(16)
        goto_inner.append(self._goto_checkmark)
        goto_inner.append(Gtk.Label(label="Go to VM"))
        self._goto_btn.set_child(goto_inner)
        self._goto_btn.add_css_class("suggested-action")
        self._goto_btn.add_css_class("pill")
        self._goto_btn.set_sensitive(False)
        self._goto_btn.set_hexpand(True)
        self._goto_btn.connect("clicked", self._on_goto_clicked)
        inner.append(self._goto_btn)

    def _pulse(self) -> bool:
        if not self._done:
            self._progress.pulse()
            return GLib.SOURCE_CONTINUE
        return GLib.SOURCE_REMOVE

    def mark_done(self, success: bool, message: str = ""):
        """Call from the main thread when provisioning completes."""
        self._done = True
        if self._pulse_source:
            GLib.source_remove(self._pulse_source)
            self._pulse_source = None

        if success:
            self._progress.set_fraction(1.0)
            self._status_label.set_markup(
                f"<span size='large' weight='bold' color='#2aad4d'>Ready</span>\n"
                f"<span color='gray' size='small'>{self._vm_name}</span>"
            )
            self._start_toggle.set_sensitive(True)
            self._start_vm = self._start_toggle.get_active()
        else:
            self._progress.set_fraction(0.0)
            self._status_label.set_markup(
                f"<span size='large' weight='bold' color='#e01b24'>Failed</span>\n"
                f"<span color='gray' size='small'>{message[:60]}</span>"
            )

        self._goto_btn.set_sensitive(True)

    def _on_goto_clicked(self, _btn):
        self.close()
        self._on_goto(self._vm_name, self._start_vm)


# ---------------------------------------------------------------------------
# Template picker dialog
# ---------------------------------------------------------------------------

class VMTemplateDialog(Adw.Window):
    """
    "New from Template" dialog.

    Shows a grid of template cards. Selecting one reveals the VM name entry,
    an optional Advanced section (vCPUs, memory), and the Create button.
    """

    def __init__(
        self,
        manager: LibvirtManager,
        on_created: Callable[[str, bool], None],
        parent_window: Gtk.Window,
    ):
        super().__init__()
        _ensure_card_css()
        self._mgr            = manager
        self._on_created     = on_created
        self._parent_window  = parent_window
        self._selected_tmpl: dict | None = None
        self._advanced_open  = False

        self.set_title("New from Template")
        # Minimum size — slightly larger than the old fixed size
        self.set_size_request(620, 560)
        # Default size on open
        self.set_default_size(640, 680)
        self.set_resizable(False)

        toolbar = Adw.ToolbarView()
        self.set_content(toolbar)

        header = Adw.HeaderBar()
        btn_cancel = Gtk.Button(label="Cancel")
        btn_cancel.connect("clicked", lambda _: self.close())
        header.pack_start(btn_cancel)

        self._btn_create = Gtk.Button(label="Create")
        self._btn_create.add_css_class("suggested-action")
        self._btn_create.set_sensitive(False)
        self._btn_create.connect("clicked", self._on_create)
        header.pack_end(self._btn_create)
        toolbar.add_top_bar(header)

        # Scrollable body
        clamp = Adw.Clamp()
        clamp.set_maximum_size(540)
        clamp.set_margin_top(16)
        clamp.set_margin_bottom(16)
        clamp.set_margin_start(16)
        clamp.set_margin_end(16)

        scroll = Gtk.ScrolledWindow()
        scroll.set_policy(Gtk.PolicyType.NEVER, Gtk.PolicyType.AUTOMATIC)
        scroll.set_vexpand(True)
        scroll.set_child(clamp)
        toolbar.set_content(scroll)

        self._body = Gtk.Box(orientation=Gtk.Orientation.VERTICAL, spacing=16)
        clamp.set_child(self._body)

        # Error banner
        self._banner = Adw.Banner()
        self._banner.set_revealed(False)
        self._body.append(self._banner)

        # ── Template grid ─────────────────────────────────────────────────
        grid_label = Gtk.Label(label="Choose a template")
        grid_label.add_css_class("title-4")
        grid_label.set_halign(Gtk.Align.START)
        self._body.append(grid_label)

        grid = Gtk.FlowBox()
        grid.set_selection_mode(Gtk.SelectionMode.SINGLE)
        grid.set_max_children_per_line(3)
        grid.set_min_children_per_line(2)
        grid.set_homogeneous(True)
        grid.set_row_spacing(16)
        grid.set_column_spacing(12)
        grid.connect("child-activated", self._on_template_selected)
        self._body.append(grid)
        self._grid = grid

        for tmpl in TEMPLATES:
            card = self._make_template_card(tmpl)
            grid.append(card)

        # ── VM name ───────────────────────────────────────────────────────
        self._config_box = Gtk.Box(orientation=Gtk.Orientation.VERTICAL, spacing=12)
        self._config_box.set_visible(False)
        self._body.append(self._config_box)

        name_group = Adw.PreferencesGroup()
        name_group.set_title("Identity")
        self._config_box.append(name_group)

        self._name_row = Adw.EntryRow()
        self._name_row.set_title("VM name")
        self._name_row.set_input_hints(Gtk.InputHints.NO_SPELLCHECK)
        self._name_row.connect("changed", self._validate)
        name_group.add(self._name_row)

        # ── Advanced (collapsible) ────────────────────────────────────────
        self._adv_expander = Adw.ExpanderRow()
        self._adv_expander.set_title("Advanced")
        self._adv_expander.set_subtitle("Adjust CPU and memory")
        name_group.add(self._adv_expander)

        self._vcpu_row = Adw.SpinRow.new_with_range(1, 32, 1)
        self._vcpu_row.set_title("vCPUs")
        self._adv_expander.add_row(self._vcpu_row)

        self._mem_row = Adw.SpinRow.new_with_range(512, 131072, 512)
        self._mem_row.set_title("Memory (MB)")
        self._adv_expander.add_row(self._mem_row)

        self._disk_row = Adw.SpinRow.new_with_range(10, 500, 10)
        self._disk_row.set_title("Disk size (GB)")
        self._adv_expander.add_row(self._disk_row)

    # ------------------------------------------------------------------ #
    # Template card                                                        #
    # ------------------------------------------------------------------ #

    def _make_template_card(self, tmpl: dict) -> Gtk.FlowBoxChild:
        child = Gtk.FlowBoxChild()
        child.set_name(tmpl["id"])
        # Disable FlowBox's own focus/selection rendering on the child
        child.set_focusable(False)

        # wrapper carries the animation CSS classes and card background
        wrapper = Gtk.Box(orientation=Gtk.Orientation.VERTICAL)
        wrapper.add_css_class("card")
        wrapper.add_css_class("tmpl-card")

        # inner box holds content with generous padding (+5% → 18px)
        box = Gtk.Box(orientation=Gtk.Orientation.VERTICAL, spacing=10)
        box.set_margin_top(18)
        box.set_margin_bottom(18)
        box.set_margin_start(18)
        box.set_margin_end(18)
        wrapper.append(box)

        # Coloured icon circle — larger to match new padding
        icon_overlay = Gtk.Overlay()
        icon_bg = Gtk.DrawingArea()
        icon_bg.set_size_request(56, 56)
        icon_bg.set_halign(Gtk.Align.CENTER)

        color = tmpl["color"]
        def draw_bg(da, cr, w, h, c=color):
            rgba = Gdk.RGBA()
            rgba.parse(c)
            cr.set_source_rgba(rgba.red, rgba.green, rgba.blue, 0.25)
            cr.arc(w/2, h/2, min(w,h)/2, 0, 2*3.14159)
            cr.fill()
        icon_bg.set_draw_func(draw_bg)

        icon = make_template_icon_image(tmpl["id"], pixel_size=28)
        icon.set_halign(Gtk.Align.CENTER)
        icon.set_valign(Gtk.Align.CENTER)

        icon_overlay.set_child(icon_bg)
        icon_overlay.add_overlay(icon)
        icon_overlay.set_halign(Gtk.Align.CENTER)
        box.append(icon_overlay)

        lbl = Gtk.Label(label=tmpl["label"])
        lbl.add_css_class("heading")
        lbl.set_halign(Gtk.Align.CENTER)
        box.append(lbl)

        sub = Gtk.Label(label=tmpl["subtitle"])
        sub.add_css_class("caption")
        sub.add_css_class("dim-label")
        sub.set_wrap(True)
        sub.set_justify(Gtk.Justification.CENTER)
        sub.set_halign(Gtk.Align.CENTER)
        box.append(sub)

        child.set_child(wrapper)

        # Hover → lift; leave → reset; press → push down; release → lift again
        motion = Gtk.EventControllerMotion.new()
        motion.connect("enter", lambda *_: wrapper.add_css_class("hover"))
        motion.connect("leave", lambda *_: (
            wrapper.remove_css_class("hover"),
            wrapper.remove_css_class("pressed"),
        ))
        child.add_controller(motion)

        click_gest = Gtk.GestureClick.new()
        click_gest.set_button(1)
        click_gest.connect("pressed", lambda *_: (
            wrapper.remove_css_class("hover"),
            wrapper.add_css_class("pressed"),
        ))
        click_gest.connect("released", lambda *_: (
            wrapper.remove_css_class("pressed"),
            wrapper.add_css_class("hover"),
        ))
        child.add_controller(click_gest)

        return child

    # ------------------------------------------------------------------ #
    # Template selection                                                   #
    # ------------------------------------------------------------------ #

    def _on_template_selected(self, grid, child):
        tmpl_id = child.get_name()
        self._selected_tmpl = next(
            (t for t in TEMPLATES if t["id"] == tmpl_id), None
        )
        if not self._selected_tmpl:
            return

        # Remove "selected" from all cards, apply to this one
        fc = grid.get_first_child()
        while fc:
            w = fc.get_child()
            if w:
                w.remove_css_class("selected")
            fc = fc.get_next_sibling()
        wrapper = child.get_child()
        if wrapper:
            wrapper.add_css_class("selected")
            wrapper.remove_css_class("hover")
            wrapper.remove_css_class("pressed")

        tmpl = self._selected_tmpl

        # Pre-fill name with template id if field is empty or was auto-set
        current = self._name_row.get_text().strip()
        if not current or current in [t["id"] for t in TEMPLATES]:
            self._name_row.set_text(tmpl_id)

        # Pre-fill advanced values
        self._vcpu_row.set_value(tmpl["vcpus"])
        self._mem_row.set_value(tmpl["memory_mb"])
        self._disk_row.set_value(tmpl["disk_gb"])

        self._config_box.set_visible(True)
        self._validate()

    # ------------------------------------------------------------------ #
    # Validation                                                           #
    # ------------------------------------------------------------------ #

    def _validate(self, *_):
        name = self._name_row.get_text().strip()
        ok   = (
            self._selected_tmpl is not None
            and bool(name)
            and " " not in name
            and name.replace("-", "").replace("_", "").isalnum()
        )
        self._btn_create.set_sensitive(ok)
        if name and not ok:
            self._name_row.add_css_class("error")
        else:
            self._name_row.remove_css_class("error")

    # ------------------------------------------------------------------ #
    # Create                                                               #
    # ------------------------------------------------------------------ #

    def _on_create(self, _btn):
        tmpl      = self._selected_tmpl
        name      = self._name_row.get_text().strip()
        vcpus     = int(self._vcpu_row.get_value())
        memory_mb = int(self._mem_row.get_value())
        disk_gb   = int(self._disk_row.get_value())

        # Close the picker — show the progress overlay
        self.close()

        overlay = VMCreationOverlay(
            parent=self._parent_window,
            vm_name=name,
            on_goto=self._on_goto,
        )
        overlay.present()

        import threading
        t = threading.Thread(
            target=self._provision,
            args=(name, tmpl, vcpus, memory_mb, disk_gb, overlay),
            daemon=True,
        )
        t.start()

    def _provision(
        self,
        name: str,
        tmpl: dict,
        vcpus: int,
        memory_mb: int,
        disk_gb: int,
        overlay: VMCreationOverlay,
    ):
        """Runs in a background thread. All GTK calls go through GLib.idle_add."""

        def _done(ok, msg=""):
            GLib.idle_add(overlay.mark_done, ok, msg)

        # 1. Create qcow2 disk image
        disk_path = f"{IMAGE_DIR}/{name}.qcow2"
        if not os.path.exists(disk_path):
            result = subprocess.run(
                ["pkexec", "qemu-img", "create", "-f", "qcow2",
                 disk_path, f"{disk_gb}G"],
                capture_output=True, text=True, timeout=60,
            )
            if result.returncode != 0:
                _done(False, f"Disk creation failed: {result.stderr.strip()}")
                return

        # 2. Define domain XML
        xml = _build_domain_xml(name, tmpl, vcpus, memory_mb)
        ok, msg = self._mgr.define_domain(xml)
        if not ok:
            _done(False, msg)
            return

        # 3. Set trust level
        self._mgr.set_trust(name, tmpl["trust"])

        _done(True)

    def _on_goto(self, name: str, start_vm: bool):
        if start_vm:
            self._mgr.start_domain(name)
        self._on_created(name)
    def present(self, parent=None):
        """Present the window, setting transient parent if supplied."""
        if parent is not None:
            root = parent.get_root() if hasattr(parent, "get_root") else parent
            if root is not None:
                self.set_transient_for(root)
        self.set_modal(True)
        super().present()
